{
  "hypotheses": [
    {
      "id": "H1",
      "parents": [],
      "operation": "generate",
      "statement": "Test a shape-aware choice among eligible existing expert GEMM backends for low-concurrency DeepSeek decode on B200. EPS-MoE establishes grouped-versus-dense selection by token count as prior work; a vLLM PR reports a small-load backend comparison on GB300 and GLM-5.2, but neither establishes the best choice or a bottleneck for this target. Profile routed tokens per expert and the full MoE path first. If backend eligibility and distinct performance regions are confirmed, capture a fixed backend for each supported batch-shape bucket and select its graph before replay. The prediction is lower decode TPOT only in buckets where expert computation exceeds selection and staging costs. A kernel-time improvement alone would not establish a serving benefit.",
      "observed_bottleneck": "Unknown for B200 DeepSeek. The supplied code confirms padding masking in an NVFP4 staging path, but supplies no target trace or measured expert GEMM share of TPOT.",
      "mechanism": "Small per-expert M can change the relative cost of grouped GEMM, dense GEMM, routing, and staging. A batch-shape bucket can select an eligible captured backend without changing allocations during graph replay.",
      "proposed_change": "After profiling and contract checks, add a small, predeclared batch-shape selection table using existing eligible backends and capture each selected path with stable buffers.",
      "code_surface": "vLLM fused-MoE backend dispatch, expert GEMM adapters, model warmup, and CUDA Graph capture setup; exact target call sites are unknown from the supplied sources.",
      "applicability": "Conditional on the target DeepSeek checkpoint, dtype, weight layout, routing semantics, and graph mode supporting at least two correct backends. These details are unknown.",
      "predicted_direction": "Potentially lower repeated C1/C4 decode TPOT in measured low-M buckets; effect size unknown. Other buckets may regress.",
      "classification": "adaptation",
      "alternatives": [
        {
          "explanation": "Host scheduling or graph replay limits TPOT even when GPU work falls.",
          "distinguishing_test": "Compare repeated TPOT with GPU busy time and host-loop timing. The supplied V4.1 PR reports a larger GPU-time reduction than TPOT reduction."
        },
        {
          "explanation": "Routing, staging, communication, or padding dominates the MoE path rather than expert GEMM.",
          "distinguishing_test": "Measure full-path time alongside expert GEMM time, routed rows, and padded rows by batch-shape bucket."
        }
      ],
      "evidence": [
        {
          "source_id": "fulltext:2410.12247",
          "quote": "switching from GroupedGemm to DenseGemm at a certain token number",
          "relation": "supports"
        },
        {
          "source_id": "github:vllm-project/vllm:54520",
          "quote": "M/rank | FlashInfer baseline (tok/s) | DeepGEMM fused (tok/s)",
          "relation": "context"
        },
        {
          "source_id": "github:vllm-project/vllm:57977",
          "quote": "C1 ×3 TPOT | 6.58 / 6.58 / 6.58 ms | 6.50 / 6.50 / 6.50 ms",
          "relation": "challenges"
        },
        {
          "source_id": "github:vllm-project/vllm:54520",
          "quote": "Keep symmetric-buffer allocation/rendezvous outside forward and CUDA Graph capture.",
          "relation": "context"
        },
        {
          "source_id": "github:vllm-project/vllm:46238",
          "quote": "TMA (Tensor Memory Accelerator) alignment faults",
          "relation": "challenges"
        },
        {
          "source_id": "github:vllm-project/vllm:60468",
          "quote": "The DeepGEMM warmup covers `fp8_gemm_nt` and the grouped MoE GEMM.",
          "relation": "context"
        }
      ],
      "novelty": {
        "scientific": "Unestablished; load-dependent grouped-versus-dense selection is prior work.",
        "implementation": "Potentially a B200 DeepSeek-specific, graph-compatible selection policy, contingent on confirming that equivalent backend choice is absent.",
        "workload": "Low-concurrency B200 DeepSeek decode; the supplied backend comparison instead used GB300 and GLM-5.2.",
        "nearest_prior_art": "EPS-MoE token-count switching; existing vLLM FlashInfer and DeepGEMM MoE integrations.",
        "specific_delta": "Measured batch-shape buckets and captured backend variants for the target configuration, if current dispatch is static."
      },
      "prior_art_query": "MoE grouped dense GEMM dispatch",
      "experiment": {
        "control": "Current vLLM dispatch, plus the best eligible existing static backend chosen using a separate tuning set.",
        "treatment": "Predeclared shape-bucket selection among the same eligible backends, with a captured path per bucket.",
        "metrics": "Repeated C1/C4 decode TPOT, GPU busy time, expert GEMM time, full MoE time, host-loop time, routed and padded rows, graph replay failures, startup and warmup cost.",
        "supports_if": "Treatment lowers repeated TPOT against both controls in prespecified low-M buckets, remains correct under graph replay, and the full-path trace attributes the difference to backend choice.",
        "rejects_if": "No eligible second backend exists, graph replay or correctness fails, or treatment does not improve TPOT against the best static control.",
        "inconclusive_if": "Kernel time improves without a resolvable TPOT change, measurement noise obscures the comparison, or concurrent effects prevent attribution.",
        "held_out_condition": "Prompt lengths and routing distributions excluded from bucket tuning, including C4 decode.",
        "correctness": "Check output agreement within the target dtype's accepted tolerance, routing and padding semantics, and repeated CUDA Graph replay across bucket boundaries.",
        "cost": "Requires target B200 GPU profiling and serving runs, graph capture for each eligible variant, and warmup accounting. No GPU execution was performed for this analysis."
      },
      "revision_reason": "The proposal is conditional because the supplied sources contain no B200 DeepSeek expert-GEMM trace and no verified target backend dispatch."
    }
  ],
  "gaps": [
    "The target DeepSeek checkpoint, quantization format, topology, graph mode, backend eligibility, and existing dispatch rule are unknown.",
    "No supplied measurement attributes B200 DeepSeek low-concurrency TPOT to expert GEMM, launch overhead, padding, or host scheduling.",
    "The V4.1 PR's GPU-time and TPOT figures are author-reported and show that GPU savings need not transfer proportionally to TPOT.",
    "The merged MegaMoE warmup PR measures first-request TTFT and startup on B300; its steady decode TPOT effect on B200 is unknown.",
    "The supplied NVFP4 code confirms masking of padded tokens, but whether the target DeepSeek path uses it, and whether padded work is material, are unknown.",
    "No second distinct adaptation is supported strongly enough to propose: launch removal and MegaMoE staging already have closely related PR implementations, while target-specific remaining costs are unmeasured."
  ]
}
